insert into mimicry_system (public_id, name, description, system_type, notes) values ('SYSTEM:000001', 'Heliconius melpomene/erato Müllerian ring', 'Demo grouping: the two reciprocal co-mimicry edges between H. melpomene and H. erato form one ring. Not a scientific claim — placeholder grouping for the demo dataset.', 'ring', 'synthetic demo grouping — labeled DEMO') on conflict (public_id) do nothing;
insert into system_interaction (system_id, interaction_id) select ms.id, mi.id from mimicry_system ms, mimicry_interaction mi where ms.public_id='SYSTEM:000001' and mi.public_id in ('MIMICRY:000007','MIMICRY:000015') on conflict do nothing;
